CREATE TABLE teams (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(500), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(30) NOT NULL, team_id BIGINT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_users_team FOREIGN KEY (team_id) REFERENCES teams(id)) ENGINE=InnoDB;
CREATE TABLE incidents (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, incident_key VARCHAR(40) NOT NULL UNIQUE, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, status VARCHAR(30) NOT NULL, priority VARCHAR(20) NOT NULL, category VARCHAR(50) NOT NULL, reporter_id BIGINT NOT NULL, assignee_id BIGINT NULL, team_id BIGINT NULL, response_due_at TIMESTAMP(6) NOT NULL, resolution_due_at TIMESTAMP(6) NOT NULL, first_response_at TIMESTAMP(6) NULL, response_breached BOOLEAN NOT NULL DEFAULT FALSE, resolution_breached BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), resolved_at TIMESTAMP(6) NULL, CONSTRAINT fk_incident_reporter FOREIGN KEY (reporter_id) REFERENCES users(id), CONSTRAINT fk_incident_assignee FOREIGN KEY (assignee_id) REFERENCES users(id), CONSTRAINT fk_incident_team FOREIGN KEY (team_id) REFERENCES teams(id), INDEX idx_incident_status_priority (status, priority), INDEX idx_incident_assignee_status (assignee_id, status), INDEX idx_incident_created (created_at), INDEX idx_incident_sla (resolution_due_at, status)) ENGINE=InnoDB;
CREATE TABLE incident_comments (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT NOT NULL, author_id BIGINT NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_comment_incident FOREIGN KEY (incident_id) REFERENCES incidents(id) ON DELETE CASCADE, CONSTRAINT fk_comment_author FOREIGN KEY (author_id) REFERENCES users(id), INDEX idx_comment_incident_created (incident_id, created_at)) ENGINE=InnoDB;
CREATE TABLE incident_history (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, incident_id BIGINT NOT NULL, actor_id BIGINT NULL, action VARCHAR(80) NOT NULL, old_value VARCHAR(500), new_value VARCHAR(500), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_history_incident FOREIGN KEY (incident_id) REFERENCES incidents(id) ON DELETE CASCADE, CONSTRAINT fk_history_actor FOREIGN KEY (actor_id) REFERENCES users(id), INDEX idx_history_incident_created (incident_id, created_at)) ENGINE=InnoDB;
CREATE TABLE sla_policies (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, priority VARCHAR(20) NOT NULL UNIQUE, response_minutes INT NOT NULL, resolution_minutes INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, incident_id BIGINT NULL, type VARCHAR(50) NOT NULL, message VARCHAR(500) NOT NULL, read_at TIMESTAMP(6) NULL, delivery_status VARCHAR(30) NOT NULL DEFAULT 'IN_APP', created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_notification_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_notification_incident FOREIGN KEY (incident_id) REFERENCES incidents(id), INDEX idx_notification_user_read (user_id, read_at, created_at)) ENGINE=InnoDB;
